import { looksLikeSvg } from './svg.js';
import { getForm } from './forms.js';
import { lstatSync, readFileSync, realpathSync } from 'node:fs';
import { isAbsolute, join, resolve, sep, win32 } from 'node:path';

const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const MAX_IMAGE_BYTES = 2 * 1024 * 1024;
const MAX_PNG_DIMENSION = 4096;
const DRAFT_KEYS = new Set(['session', 'template', 'blocks', 'form']);
// Optional contents of the form's own parts (engine/forms/<id>/form.json): title, goal table rows
// and the rows of the table that closes the body. Shapes are checked against the draft's template;
// without a template the engine checks them against the target's form.
const FORM_KEYS = new Set(['title', 'goals', 'summary']);
const SESSION_KEYS = new Set(['date', 'project']);
const BULLET_TYPES = new Set(['bullet1', 'bullet2', 'bullet3', 'bullet4']);
const BULLET_KEYS = new Set(['type', 'text', 'source']);
// Research-report outline levels; the engine writes the 가./1)/(1) labels and ◯/- markers.
const OUTLINE_TYPES = new Set(['heading1', 'heading2', 'heading3', 'statement', 'detail']);
const HEADING_TYPES = new Set(['heading1', 'heading2', 'heading3']);
const OUTLINE_LABEL_RE = /^(?:[가-하]\.|\d+\)|\(\d+\))\s/;
const FIGURE_GRID_KEYS = new Set(['type', 'images', 'columns', 'caption', 'captionStyle', 'source']);
const CAPTION_STYLES = new Set(['number', 'angle']);
const TABLE_KEYS = new Set(['type', 'headers', 'rows', 'colWidthRatios', 'merges', 'caption', 'source']);
const MERGE_KEYS = new Set(['row', 'col', 'rowSpan', 'colSpan']);

export function validateDraft(draft, projectRoot) {
  const errors = [];

  try {
    if (!isObject(draft)) {
      errors.push('draft must be an object');
      return result(errors);
    }

    validateAllowedKeys(draft, DRAFT_KEYS, 'draft', errors);
    validateSession(draft.session, errors);
    let template = null;
    if (Object.hasOwn(draft, 'template')) {
      try {
        template = getForm(draft.template);
      } catch (error) {
        errors.push(`template: ${errorMessage(error)}`);
      }
    }
    if (Object.hasOwn(draft, 'form')) {
      validateForm(draft.form, template, errors);
    }

    if (!Array.isArray(draft.blocks)) {
      errors.push('blocks must be a nonempty array');
      return result(errors);
    }
    if (draft.blocks.length === 0) {
      errors.push('blocks must be a nonempty array');
    }

    draft.blocks.forEach((block, index) => {
      validateBlock(block, index, projectRoot, errors);
    });
  } catch (error) {
    errors.push(`validation failed: ${errorMessage(error)}`);
  }

  return result(errors);
}

export function checkImage(relPath, projectRoot) {
  const errors = [];
  let width;
  let height;

  try {
    if (!nonemptyString(relPath)) {
      errors.push('image path must be a nonempty string');
      return imageResult(errors, width, height);
    }
    if (!nonemptyString(projectRoot)) {
      errors.push('projectRoot must be a nonempty string');
      return imageResult(errors, width, height);
    }

    if (isAbsolute(relPath) || win32.isAbsolute(relPath)) {
      errors.push(`image path must be relative: ${relPath}`);
    }

    const parts = relPath.split(/[\\/]+/).filter(Boolean);
    if (parts.length === 0) {
      errors.push('image path must not be empty');
    }
    if (parts.includes('..')) {
      errors.push(`image path must not contain ..: ${relPath}`);
    }
    if (errors.length > 0) {
      return imageResult(errors, width, height);
    }

    const root = resolve(projectRoot);
    let rootReal;
    try {
      rootReal = realpathSync(root);
    } catch (error) {
      errors.push(`projectRoot cannot be resolved: ${errorMessage(error)}`);
      return imageResult(errors, width, height);
    }

    let current = root;
    let finalStat;
    for (const part of parts) {
      current = join(current, part);
      let stat;
      try {
        stat = lstatSync(current);
      } catch (error) {
        errors.push(`image path component cannot be read: ${part}: ${errorMessage(error)}`);
        return imageResult(errors, width, height);
      }
      if (stat.isSymbolicLink()) {
        errors.push(`image path must not contain symlink components: ${relPath}`);
        return imageResult(errors, width, height);
      }
      finalStat = stat;
    }

    let fileReal;
    try {
      fileReal = realpathSync(current);
    } catch (error) {
      errors.push(`image path cannot be resolved: ${errorMessage(error)}`);
      return imageResult(errors, width, height);
    }

    if (!containsPath(rootReal, fileReal)) {
      errors.push(`image path escapes project root: ${relPath}`);
    }
    if (!finalStat?.isFile()) {
      errors.push(`image path must point to a file: ${relPath}`);
    }
    if (finalStat && finalStat.size > MAX_IMAGE_BYTES) {
      errors.push(`image file exceeds 2MB: ${relPath}`);
    }
    if (errors.length > 0) {
      return imageResult(errors, width, height);
    }

    const data = readFileSync(current);
    // Hancom Office does not show an SVG embedded by the engine (user check, 2026-09-29), and rhwp
    // skips raster parts inside one; drafts use PNG. The engine can still embed SVG for rhwp work.
    if (looksLikeSvg(data)) {
      errors.push(`SVG is not shown by Hancom Office; use a PNG of at least 300 dpi at print size: ${relPath}`);
      return imageResult(errors, width, height);
    }
    if (data.length < PNG_SIGNATURE.length || !data.subarray(0, PNG_SIGNATURE.length).equals(PNG_SIGNATURE)) {
      errors.push(`image file must be a PNG: ${relPath}`);
      return imageResult(errors, width, height);
    }
    if (data.length < 24) {
      errors.push(`image file is missing IHDR dimensions: ${relPath}`);
      return imageResult(errors, width, height);
    }

    width = data.readUInt32BE(16);
    height = data.readUInt32BE(20);
    if (width > MAX_PNG_DIMENSION || height > MAX_PNG_DIMENSION) {
      errors.push(`image dimensions exceed 4096px: ${relPath}`);
    }
  } catch (error) {
    errors.push(`image validation failed: ${errorMessage(error)}`);
  }

  return imageResult(errors, width, height);
}

function validateForm(form, template, errors) {
  if (!isObject(form)) {
    errors.push('form must be an object');
    return;
  }
  validateAllowedKeys(form, FORM_KEYS, 'form', errors);
  if (Object.hasOwn(form, 'title')) {
    if (!nonemptyString(form.title)) {
      errors.push('form.title must be a nonempty string');
    } else if (template && !template.title) {
      errors.push(`form.title: form "${template.id}" has no title paragraph`);
    }
  }
  for (const key of ['goals', 'summary']) {
    if (!Object.hasOwn(form, key)) {
      continue;
    }
    const shape = template ? template.tables?.[key] : { columns: null, maxRows: 20 };
    if (!shape) {
      errors.push(`form.${key}: form "${template.id}" has no ${key} table`);
      continue;
    }
    const rows = form[key];
    if (!Array.isArray(rows) || rows.length === 0 || rows.length > shape.maxRows) {
      errors.push(`form.${key} must be an array of 1-${shape.maxRows} rows`);
      continue;
    }
    rows.forEach((row, index) => {
      if (!Array.isArray(row) || (shape.columns !== null && row.length !== shape.columns)
          || !row.every((cell) => typeof cell === 'string')) {
        errors.push(`form.${key}[${index}] must be an array of ${shape.columns ?? 'the table\'s'} strings`);
      }
    });
  }
}

function validateSession(session, errors) {
  if (!isObject(session)) {
    errors.push('session must be an object');
    return;
  }
  validateAllowedKeys(session, SESSION_KEYS, 'session', errors);
  if (typeof session.date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(session.date)) {
    errors.push('session.date must match YYYY-MM-DD');
  }
  if (!nonemptyString(session.project)) {
    errors.push('session.project must be a nonempty string');
  }
}

function validateBlock(block, index, projectRoot, errors) {
  const prefix = `blocks[${index}]`;
  if (!isObject(block)) {
    errors.push(`${prefix} must be an object`);
    return;
  }

  const type = block.type;
  if (BULLET_TYPES.has(type)) {
    validateAllowedKeys(block, BULLET_KEYS, prefix, errors);
    validateOptionalSource(block, prefix, errors);
    if (!nonemptyString(block.text)) {
      errors.push(`${prefix}.text must be a nonempty string`);
    }
    return;
  }

  if (OUTLINE_TYPES.has(type)) {
    validateAllowedKeys(block, BULLET_KEYS, prefix, errors);
    validateOptionalSource(block, prefix, errors);
    if (!nonemptyString(block.text)) {
      errors.push(`${prefix}.text must be a nonempty string`);
    } else if (HEADING_TYPES.has(type) && OUTLINE_LABEL_RE.test(block.text.trimStart())) {
      errors.push(`${prefix}.text must not start with a number label; the engine numbers headings`);
    }
    return;
  }

  if (type === 'figure_grid') {
    validateAllowedKeys(block, FIGURE_GRID_KEYS, prefix, errors);
    validateOptionalSource(block, prefix, errors);
    validateFigureGrid(block, prefix, projectRoot, errors);
    return;
  }

  if (type === 'table') {
    validateAllowedKeys(block, TABLE_KEYS, prefix, errors);
    validateOptionalSource(block, prefix, errors);
    validateTable(block, prefix, errors);
    return;
  }

  errors.push(`${prefix}.type is not supported: ${String(type)}`);
}

function validateFigureGrid(block, prefix, projectRoot, errors) {
  if (!Array.isArray(block.images) || block.images.length < 1 || block.images.length > 6) {
    errors.push(`${prefix}.images must contain 1 to 6 paths`);
  } else {
    block.images.forEach((imagePath, imageIndex) => {
      const checked = checkImage(imagePath, projectRoot);
      for (const error of checked.errors) {
        errors.push(`${prefix}.images[${imageIndex}]: ${error}`);
      }
    });
  }

  if (Object.hasOwn(block, 'columns')) {
    if (!Number.isInteger(block.columns) || block.columns < 1 || block.columns > 3) {
      errors.push(`${prefix}.columns must be an integer from 1 to 3`);
    }
  }

  if (!nonemptyString(block.caption)) {
    errors.push(`${prefix}.caption must be a nonempty string`);
  }
  if (Object.hasOwn(block, 'captionStyle') && !CAPTION_STYLES.has(block.captionStyle)) {
    errors.push(`${prefix}.captionStyle must be "number" or "angle"`);
  }
}

function validateTable(block, prefix, errors) {
  if (Object.hasOwn(block, 'caption') && !nonemptyString(block.caption)) {
    errors.push(`${prefix}.caption must be a nonempty string when present`);
  }
  const headersOk = Array.isArray(block.headers)
    && block.headers.length > 0
    && block.headers.every((header) => typeof header === 'string');
  if (!headersOk) {
    errors.push(`${prefix}.headers must be an array of strings`);
  }

  if (!Array.isArray(block.rows)) {
    errors.push(`${prefix}.rows must be an array`);
    return;
  }

  const headerLength = Array.isArray(block.headers) ? block.headers.length : 0;
  block.rows.forEach((row, rowIndex) => {
    if (!Array.isArray(row)) {
      errors.push(`${prefix}.rows[${rowIndex}] must be an array`);
      return;
    }
    if (row.length !== headerLength) {
      errors.push(`${prefix}.rows[${rowIndex}] must have ${headerLength} cells`);
    }
  });

  const covered = validateMerges(block, prefix, headerLength, errors);

  if (headersOk) {
    block.headers.forEach((header, col) => {
      if (!nonemptyString(header) && !covered.has(`0:${col}`)) {
        errors.push(`${prefix}.headers[${col}] must be a nonempty string (only merge-covered headers may be empty)`);
      }
    });
  }
  block.rows.forEach((row, rowIndex) => {
    if (!Array.isArray(row)) {
      return;
    }
    row.forEach((value, col) => {
      if (covered.has(`${rowIndex + 1}:${col}`) && value !== '') {
        errors.push(`${prefix}.rows[${rowIndex}][${col}] is covered by a merge and must be an empty string`);
      }
    });
  });

  if (Object.hasOwn(block, 'colWidthRatios')) {
    const ratios = block.colWidthRatios;
    const ratiosOk = Array.isArray(ratios)
      && ratios.length === headerLength
      && ratios.every((ratio) => Number.isFinite(ratio) && ratio > 0);
    if (!ratiosOk) {
      errors.push(`${prefix}.colWidthRatios must be ${headerLength} positive finite numbers`);
    } else if (Math.max(...ratios) / Math.min(...ratios) > 20) {
      errors.push(`${prefix}.colWidthRatios spread exceeds 20x (would produce a near-invisible column)`);
    }
  }
}

function validateMerges(block, prefix, headerLength, errors) {
  const covered = new Set();
  if (!Object.hasOwn(block, 'merges')) {
    return covered;
  }
  if (!Array.isArray(block.merges) || block.merges.length > 20) {
    errors.push(`${prefix}.merges must be an array of at most 20 merge specs`);
    return covered;
  }
  const rowCount = Array.isArray(block.rows) ? block.rows.length + 1 : 1;
  const occupied = new Set();
  block.merges.forEach((merge, mergeIndex) => {
    const mergePrefix = `${prefix}.merges[${mergeIndex}]`;
    if (!isObject(merge)) {
      errors.push(`${mergePrefix} must be an object`);
      return;
    }
    validateAllowedKeys(merge, MERGE_KEYS, mergePrefix, errors);
    const fieldsOk = ['row', 'col', 'rowSpan', 'colSpan'].every((key) => Number.isInteger(merge[key]))
      && merge.row >= 0 && merge.col >= 0 && merge.rowSpan >= 1 && merge.colSpan >= 1;
    if (!fieldsOk) {
      errors.push(`${mergePrefix} must have integer row/col >= 0 and rowSpan/colSpan >= 1`);
      return;
    }
    if (merge.rowSpan * merge.colSpan < 2) {
      errors.push(`${mergePrefix} must span more than one cell`);
      return;
    }
    if (merge.row + merge.rowSpan > rowCount || merge.col + merge.colSpan > headerLength) {
      errors.push(`${mergePrefix} exceeds the ${rowCount}x${headerLength} table grid`);
      return;
    }
    for (let row = merge.row; row < merge.row + merge.rowSpan; row += 1) {
      for (let col = merge.col; col < merge.col + merge.colSpan; col += 1) {
        const key = `${row}:${col}`;
        if (occupied.has(key)) {
          errors.push(`${mergePrefix} overlaps another merge at cell ${key}`);
          return;
        }
        occupied.add(key);
        if (row !== merge.row || col !== merge.col) {
          covered.add(key);
        }
      }
    }
  });
  return covered;
}

function validateAllowedKeys(value, allowedKeys, prefix, errors) {
  for (const key of Object.keys(value)) {
    if (!allowedKeys.has(key)) {
      errors.push(`${prefix}.${key} is not allowed`);
    }
  }
}

function validateOptionalSource(block, prefix, errors) {
  if (Object.hasOwn(block, 'source') && typeof block.source !== 'string') {
    errors.push(`${prefix}.source must be a string when present`);
  }
}

function containsPath(rootReal, fileReal) {
  return fileReal === rootReal || fileReal.startsWith(rootReal.endsWith(sep) ? rootReal : `${rootReal}${sep}`);
}

function isObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function nonemptyString(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

function result(errors) {
  return { ok: errors.length === 0, errors };
}

function imageResult(errors, width, height) {
  return { ok: errors.length === 0, errors, width, height };
}

function errorMessage(error) {
  return error instanceof Error ? error.message : String(error);
}
